import { join } from 'node:path'

export const GENERATED_BANNER =
  'AUTO-GENERATED by KunYu Studio — 请勿手动编辑。\n * 由可视化编辑器根据 .kunyu/content 语义资产生成，修改请在可视化编辑器中进行。'

export function rel(root: string, p: string): string {
  return join(p).replace(join(root), '').replace(/^[\\/]/, '').split('\\').join('/')
}

export function oneLine(s: string): string {
  return s.replace(/\s+/g, ' ').trim().slice(0, 120)
}

export function clampStack(n: number): number {
  if (!Number.isFinite(n)) return 64
  return Math.min(64, Math.max(1, Math.floor(n)))
}

/** id → PascalCase 类名片段（goblin_knight → GoblinKnight） */
export function pascal(id: string): string {
  return id
    .split(/[^a-zA-Z0-9]+/)
    .filter(Boolean)
    .map((s) => s.charAt(0).toUpperCase() + s.slice(1))
    .join('')
}
